const FD = 'https://www.foodsdictionary.co.il/Products/';
const fd = slug => ({ label: 'FoodsDictionary', url: FD + slug.split('/').map(encodeURIComponent).join('/') });

const f = (id, name, brand, category, kinds, pack, art, slug, ingredients, summary, short) =>
  ({ id, kinds, name, brand, category, art, pack, short, ingredients, summary, source: fd(slug) });

